            vm.startPrank(user);
            target.transfer(pair, swapThreshold);
            vm.stopPrank();
        }

        uint256 finalBalance = address(TARGET).balance;
        console.log("Final ETH balance:", finalBalance);

        // ETH should be stuck because marketing wallet rejects payments
        assertEq(finalBalance, initialBalance, "ETH should be stuck in contract");
        assertEq(address(this).balance, 10 ether, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

